package com.quincaisoft.inventory.application;
import com.quincaisoft.inventory.api.InventoryBootstrapService;import com.quincaisoft.inventory.infrastructure.*;import com.quincaisoft.shared.BootstrapScope;import jakarta.persistence.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.util.*;import java.time.*;
@Service public class DefaultInventoryBootstrapService implements InventoryBootstrapService { private final EntityManager em; public DefaultInventoryBootstrapService(EntityManager em){this.em=em;}
@Transactional(propagation=Propagation.MANDATORY) public void initialize(BootstrapScope s,UUID warehouseId,String name) {require(s);var w=new BootstrapWarehouse();w.tenantId=s.tenantId();w.companyId=s.companyId();w.branchId=s.branchId();w.id=warehouseId;w.name=name;w.active=true;w.lockVersion=0;em.persist(w);em.flush();}
private void require(BootstrapScope s) { if(!em.isJoinedToTransaction()) throw new IllegalStateException("Bootstrap must join platform transaction"); Number n=(Number)em.createNativeQuery(BootstrapScope.AUTHORIZATION_SQL).setParameter("p",s.provisioningId()).setParameter("t",s.tenantId()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("o",s.ownerId()).getSingleResult(); if(n.longValue()!=1)throw new org.springframework.security.access.AccessDeniedException("Approved current platform bootstrap required"); }
}
